changeSet.sql:
ALTER TABLE workspace ADD COLUMN practice_repository_coverage_mode VARCHAR(24) NOT NULL DEFAULT 'ALL_MONITORED';
ALTER TABLE workspace ADD COLUMN practice_person_coverage_mode VARCHAR(24) NOT NULL DEFAULT 'ALL_ELIGIBLE';
ALTER TABLE workspace ADD COLUMN practice_delivery_status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE';
ALTER TABLE workspace ADD COLUMN practice_rollout_revision BIGINT NOT NULL DEFAULT 0;
ALTER TABLE workspace ADD COLUMN practice_config_version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE workspace ADD CONSTRAINT chk_workspace_practice_repository_coverage
    CHECK (practice_repository_coverage_mode IN ('ALL_MONITORED', 'SELECTED'));
ALTER TABLE workspace ADD CONSTRAINT chk_workspace_practice_person_coverage
    CHECK (practice_person_coverage_mode IN ('ALL_ELIGIBLE', 'SELECTED'));
ALTER TABLE workspace ADD CONSTRAINT chk_workspace_practice_delivery_status
    CHECK (practice_delivery_status IN ('ACTIVE', 'PAUSED'));

ALTER TABLE practice_review_repository_target ADD CONSTRAINT chk_practice_review_repository_target_branches
    CHECK (jsonb_typeof(base_branches) = 'array'
        AND NOT jsonb_path_exists(base_branches, '$[*] ? (@.type() != "string" || @ like_regex "^\\s*$" || @ like_regex "^.{255}.")'));

UPDATE workspace SET practice_repository_coverage_mode = 'SELECTED' WHERE practice_review_scope IS NOT NULL AND (jsonb_array_length(COALESCE(practice_review_scope -> 'repositories', '[]'::jsonb)) > 0 OR jsonb_array_length(COALESCE(practice_review_scope -> 'targetBranches', '[]'::jsonb)) > 0);
-- The source scope has one workspace-wide branch list; copy it to each selected repository. INSERT INTO practice_review_repository_target (workspace_id, repository_monitor_id, base_branches) SELECT w.id, r.id, COALESCE(w.practice_review_scope -> 'targetBranches', '[]'::jsonb) FROM workspace w JOIN repository_to_monitor r ON r.workspace_id = w.id WHERE w.practice_repository_coverage_mode = 'SELECTED' AND (jsonb_array_length(COALESCE(w.practice_review_scope -> 'repositories', '[]'::jsonb)) = 0 OR r.name_with_owner IN (SELECT jsonb_array_elements_text(w.practice_review_scope -> 'repositories')));
ALTER TABLE workspace DROP CONSTRAINT IF EXISTS chk_workspace_review_scope; ALTER TABLE workspace DROP COLUMN practice_review_scope;

rollback.sql:
UPDATE workspace w SET practice_review_scope = jsonb_build_object(
    'repositories', COALESCE((SELECT jsonb_agg(r.name_with_owner ORDER BY r.name_with_owner)
        FROM practice_review_repository_target t JOIN repository_to_monitor r ON r.id = t.repository_monitor_id
        WHERE t.workspace_id = w.id), '[]'::jsonb),
    'targetBranches', COALESCE((SELECT jsonb_agg(DISTINCT branch.value)
        FROM practice_review_repository_target t
        CROSS JOIN LATERAL jsonb_array_elements_text(t.base_branches) branch(value)
        WHERE t.workspace_id = w.id), '[]'::jsonb)
) WHERE w.practice_repository_coverage_mode = 'SELECTED';
ALTER TABLE workspace ADD CONSTRAINT chk_workspace_review_scope CHECK (practice_review_scope IS NULL OR jsonb_typeof(practice_review_scope) = 'object');

changeSet.sql:
ALTER TABLE feedback_dispatch ADD CONSTRAINT chk_feedback_dispatch_state
    CHECK (state IN ('PENDING', 'CLAIMED', 'SENT', 'SUPPRESSED', 'UNCERTAIN', 'FAILED'));
ALTER TABLE feedback_dispatch ADD CONSTRAINT chk_feedback_dispatch_destination
    CHECK (destination IN ('AUTOMATIC_REVIEW_PACKAGE', 'APPROVED_REVIEW_PACKAGE')
        AND (destination = 'APPROVED_REVIEW_PACKAGE') = (feedback_id IS NOT NULL));
ALTER TABLE feedback_dispatch ADD CONSTRAINT chk_feedback_dispatch_practice_slugs
    CHECK (jsonb_typeof(practice_slugs) = 'array'
        AND NOT jsonb_path_exists(practice_slugs, '$[*] ? (@.type() != "string")'));
ALTER TABLE feedback_dispatch ADD CONSTRAINT chk_feedback_dispatch_package
    CHECK (jsonb_typeof(package_content) = 'object'
        AND jsonb_typeof(delivered_placements) = 'array');
ALTER TABLE feedback_dispatch ADD CONSTRAINT chk_feedback_dispatch_lease
    CHECK ((state = 'CLAIMED') = (lease_owner IS NOT NULL AND lease_expires_at IS NOT NULL));
ALTER TABLE feedback_dispatch ADD CONSTRAINT chk_feedback_dispatch_delivery
    CHECK (state <> 'SENT' OR delivered_external_ref IS NOT NULL
        OR jsonb_array_length(delivered_placements) > 0 OR body = '');
ALTER TABLE feedback_dispatch ADD CONSTRAINT chk_feedback_dispatch_suppression
    CHECK ((state = 'SUPPRESSED') = (suppression_reason IS NOT NULL));
ALTER TABLE feedback_dispatch ADD CONSTRAINT chk_feedback_dispatch_projection
    CHECK ((projection_owner IS NULL) = (projection_expires_at IS NULL));
ALTER TABLE feedback DROP CONSTRAINT chk_feedback_suppression_reason;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_suppression_reason
    CHECK (suppression_reason IS NULL OR suppression_reason IN (
        'VOLUME_CAPPED', 'COMPOSER_DEDUPED', 'REACTED_DISPUTED', 'REACTED_NOT_APPLICABLE',
        'CONVERSATION_EXPIRED', 'ARTIFACT_GONE', 'ARTIFACT_CLOSED', 'ARTIFACT_MERGED',
        'ARTIFACT_DRAFT', 'RECIPIENT_OPTED_OUT', 'EMPTY_AFTER_SANITIZE', 'INSTANCE_SILENCED',
        'PRACTICE_REQUIRES_APPROVAL', 'BACKFILL_QUIET', 'WORKSPACE_DISABLED', 'APPROVAL_STALE',
        'APPROVAL_NO_LONGER_ELIGIBLE', 'WORKSPACE_DELIVERY_PAUSED', 'STALE_ROLLOUT_REVISION',
        'OUTSIDE_CURRENT_COVERAGE'));

rollback.sql:
UPDATE feedback SET suppression_reason = 'WORKSPACE_DISABLED'
 WHERE suppression_reason IN ('WORKSPACE_DELIVERY_PAUSED', 'STALE_ROLLOUT_REVISION', 'OUTSIDE_CURRENT_COVERAGE');
ALTER TABLE feedback DROP CONSTRAINT IF EXISTS chk_feedback_suppression_reason;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_suppression_reason
    CHECK (suppression_reason IS NULL OR suppression_reason IN (
        'VOLUME_CAPPED', 'COMPOSER_DEDUPED', 'REACTED_DISPUTED', 'REACTED_NOT_APPLICABLE',
        'CONVERSATION_EXPIRED', 'ARTIFACT_GONE', 'ARTIFACT_CLOSED', 'ARTIFACT_MERGED',
        'ARTIFACT_DRAFT', 'RECIPIENT_OPTED_OUT', 'EMPTY_AFTER_SANITIZE', 'INSTANCE_SILENCED',
        'PRACTICE_REQUIRES_APPROVAL', 'BACKFILL_QUIET', 'WORKSPACE_DISABLED', 'APPROVAL_STALE',
        'APPROVAL_NO_LONGER_ELIGIBLE'));

changeSet.sql:
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_proposed_placements
    CHECK (jsonb_typeof(proposed_placements) = 'array');
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_proposed_practice_slugs
    CHECK (jsonb_typeof(proposed_practice_slugs) = 'array'
        AND NOT jsonb_path_exists(proposed_practice_slugs, '$[*] ? (@.type() != "string")'));
ALTER TABLE feedback DROP CONSTRAINT chk_feedback_state;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_state
    CHECK (delivery_state IN ('AWAITING_APPROVAL', 'PREPARED', 'PARTIALLY_DELIVERED', 'PARTIALLY_FAILED', 'DELIVERED',
        'DISCARDED', 'SUPERSEDED', 'SUPPRESSED', 'FAILED'));

rollback.sql:
UPDATE feedback SET delivery_state = 'FAILED', suppression_reason = NULL
 WHERE delivery_state IN ('PARTIALLY_DELIVERED', 'PARTIALLY_FAILED');
ALTER TABLE feedback DROP CONSTRAINT chk_feedback_state;
ALTER TABLE feedback ADD CONSTRAINT chk_feedback_state
    CHECK (delivery_state IN ('AWAITING_APPROVAL', 'PREPARED', 'DELIVERED', 'DISCARDED',
        'SUPERSEDED', 'SUPPRESSED', 'FAILED'));
